from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    tokens = rule.split()
    frequency = tokens[0]
    interval = int(tokens[1])
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if frequency == "DAILY":
        return [
            (start_date + timedelta(days=i * interval)).isoformat()
            for i in range(count)
        ]

    result = []
    period = 0

    if frequency == "WEEKLY":
        monday = start_date - timedelta(days=start_date.weekday())
        selected = sorted(weekdays[code] for code in tokens[2].split(","))

        while len(result) < count:
            week_start = monday + timedelta(weeks=period * interval)
            for weekday in selected:
                candidate = week_start + timedelta(days=weekday)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            period += 1

    if frequency == "YEARLY":
        month, day = map(int, tokens[2].split("-"))

        while len(result) < count:
            year = start_date.year + period * interval
            period += 1
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())

        return result

    # MONTHLY: either a numbered day or an ordinal weekday.
    initial_month = start_date.year * 12 + start_date.month - 1

    while len(result) < count:
        month_index = initial_month + period * interval
        year, month_zero_based = divmod(month_index, 12)
        month = month_zero_based + 1
        period += 1

        first_weekday, last_day = monthrange(year, month)

        if len(tokens) == 3:
            requested_day = int(tokens[2])
            day = last_day if requested_day == -1 else requested_day
        else:
            ordinal = int(tokens[2])
            weekday = weekdays[tokens[3]]
            if ordinal == -1:
                last_weekday = (first_weekday + last_day - 1) % 7
                day = last_day - (last_weekday - weekday) % 7
            else:
                day = 1 + (weekday - first_weekday) % 7 + 7 * (ordinal - 1)

        if day <= last_day:
            candidate = date(year, month, day)
            if candidate >= start_date:
                result.append(candidate.isoformat())

    return result
